import * as React from "react"

import { layerProps, type LayerProps } from "@/components/standard/layer"

const gradientKinds = ["linear", "radial", "conic", "mesh"] as const

type GradientKind = (typeof gradientKinds)[number]

const defaultGradientColors = [
  "oklch(0.7 0.2 300)",
  "oklch(0.8 0.15 200)",
  "oklch(0.85 0.15 85)",
]

/** Where mesh color spots sit, in order. Repeats past the last one. */
const meshSpots = [
  "20% 20%",
  "80% 25%",
  "50% 90%",
  "10% 80%",
  "90% 85%",
  "50% 45%",
]

type GradientProps = LayerProps & {
  kind?: GradientKind
  /** Any CSS colors, including theme vars like `var(--primary)`. */
  colors?: string[]
  /** Degrees, for linear and conic. */
  angle?: number
  /** Center for radial and conic, e.g. "50% 0%". */
  at?: string
}

function gradientImage(
  kind: GradientKind,
  colors: string[],
  angle: number,
  at: string
) {
  const stops = colors.join(", ")

  switch (kind) {
    case "linear":
      return `linear-gradient(${angle}deg, ${stops})`
    case "radial":
      return `radial-gradient(circle at ${at}, ${stops})`
    case "conic":
      return `conic-gradient(from ${angle}deg at ${at}, ${stops}, ${colors[0]})`
    case "mesh":
      return colors
        .map(
          (color, index) =>
            `radial-gradient(at ${meshSpots[index % meshSpots.length]}, ${color} 0, transparent 60%)`
        )
        .join(", ")
  }
}

/** Color transition layer: linear, radial, conic or mesh. */
function Gradient({
  kind = "linear",
  colors = defaultGradientColors,
  angle = 135,
  at = "50% 50%",
  ...layer
}: GradientProps) {
  const props = layerProps(layer, "gradient")

  return (
    <div
      {...props}
      data-kind={kind}
      style={{
        backgroundImage: gradientImage(kind, colors, angle, at),
        ...props.style,
      }}
    />
  )
}

export { Gradient, gradientKinds, type GradientKind, type GradientProps }

import type * as React from "react"
import { cn } from "cn"

/**
 * Shared props for the layer primitives (Gradient, Noise, Pattern, Color
 * Grade, Distort, Mask). Put layers inside any `relative isolate` parent:
 * `behind` sits under the parent's content but above its background, `over`
 * sits on top of the content.
 */
type LayerPlacement = "behind" | "over"

type LayerBlend = Extract<
  React.CSSProperties["mixBlendMode"],
  | "normal"
  | "multiply"
  | "screen"
  | "overlay"
  | "soft-light"
  | "hard-light"
  | "color-dodge"
  | "color-burn"
  | "difference"
  | "luminosity"
  | "color"
>

type LayerProps = {
  placement?: LayerPlacement
  blend?: LayerBlend
  /** 0–1. */
  opacity?: number
  className?: string
  style?: React.CSSProperties
}

/** Class and style for an absolutely positioned, non-interactive layer. */
function layerProps(
  { placement = "behind", blend, opacity, className, style }: LayerProps,
  slot: string
) {
  return {
    "aria-hidden": true,
    "data-slot": slot,
    "data-placement": placement,
    className: cn(
      "pointer-events-none absolute inset-0 rounded-[inherit] forced-colors:hidden",
      placement === "behind" ? "-z-10" : "z-10",
      className
    ),
    style: { mixBlendMode: blend, opacity, ...style },
  } as const
}

/** SVG markup as a CSS url(), for textures that need no DOM. */
function svgUrl(svg: string) {
  return `url("data:image/svg+xml,${encodeURIComponent(svg)}")`
}

export { layerProps, svgUrl, type LayerBlend, type LayerPlacement, type LayerProps }
